  `willingness_declaration_attachment` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `needs_statement_attachment` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `other_documents_attachment` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
