INSERT INTO `kaaba_scholarship` VALUES (1,'Higher Education Scholarship','Programmes: Diploma / BSc Equivalent qualifications.\r\nCoverage: Tuition and Possible Learning Support.\r\nTarget: Girls/Women aged 15–35.\r\nEligibility: Secondary School Certificates (relevant to field of study) + Merit + Need + ID.',1,'2025-11-28','34f0ccd7-2f59-4c3a-81fc-9b47668e17b8','Deeqaha Waxbarasho ee Heerka Tacliinta Sare','Barnaamijyada: Shahaado Diploma ah / Shahaado u dhiganta BSc.\nDaboolidda: Kharashka waxbarashada iyo taageero waxbarasho oo suurtagal ah.\nBartilmaameed: Gabdhaha/Dumarka da’doodu u dhaxayso 15–35 sano.\nU-qalmitaanka: Shahaadooyinka Dugsiga Sare (ku habboon laanta waxbarasho) + Aqoontooda + Baahida + Aqoonsi.','h'),(2,'TVET Scholarship','Programmes: Short-cycle, market-relevant skills training with employability focus.\r\nCoverage: Tuition and Possible Learning Support.\r\nTarget: Girls/Women aged 15–35.\r\nEligibility: Secondary School Certificates OR Minimum Level 4 Literacy',1,'2025-11-28','c13e6c74-ab14-4869-b976-7b15b478035a','Deeqaha Waxbarasho ee TVET (Tababarka Farsamada iyo Xirfadaha)','Barnaamijyada: Tababaro xirfadeed oo gaagaaban, la jaanqaadaya baahida suuqa shaqada, kuna saleysan kor u qaadista fursadaha shaqo.\nDaboolidda: Kharashka waxbarashada iyo taageero waxbarasho oo suurtagal ah.\nBartilmaameed: Gabdhaha/Dumarka da’doodu u dhaxayso 15–35 sano.\nU-qalmitaanka: Shahaadooyinka Dugsiga Sare ama ugu yaraan Heerka 4 ee aqoonta akhris- qoris iyo xisaab + Aqoontooda + Baahida + Aqoonsi rasmi ah.','t'),(3,'Literacy & Numeracy Scholarship','Programmes: Literacy and Numeracy and Basic Life Skills Training.\r\nCoverage: Tuition and Possible Learning Support.\r\nTarget: Girls/Women aged 15–35.\r\nEligibility: Merit + Need + ID.',0,'2025-11-30','d62a9f8e-29df-4000-8a03-9610338a18e0','Deeqaha waxbarasho ee akhris-qoris iyo xisaab (Literacy & Numeracy)','Barnaamijyada: Tababaro ku saabsan akhris-qoris, xisaab, iyo xirfadaha nolosha aasaasiga ah.\nDaboolidda: Kharashka waxbarashada iyo taageero waxbarasho oo suurtagal ah.\nBartilmaameed: Gabdhaha/Dumarka da’doodu u dhaxayso 15–35 sano.\nU-qalmitaanka: Aqoontooda + Baahida waxbarasho + Aqoonsi rasmi ah.\n\n','l');
/*!40000 ALTER TABLE `kaaba_scholarship` ENABLE KEYS */;
UNLOCK TABLES;

